<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Media extends Model { protected $fillable=['uploaded_by','disk','path','original_name','mime_type','size_bytes','width','height','alt_text']; protected $appends=['url']; protected $casts=['size_bytes'=>'integer']; public function getUrlAttribute():string{return \Storage::disk($this->disk)->url($this->path);} }
